commands.command:
sudo chown -R inventorysvc:inventory-readers /srv/inventory
sudo find /srv/inventory -type d -exec chmod 750 {} \;
sudo find /srv/inventory -type f -exec chmod 640 {} \;
find /srv/inventory -exec ls -lad {} \;
echo ---
cat /srv/inventory/data/records.csv
cat /srv/inventory/data/config.json
